script:
frappe.ui.form.on("Delivery Order Towing", {
	refresh(frm) {
		if (frm.is_new()) return;

		frappe.call({
			method: "live_tracking.api.staff.get_links_for_reference",
			args: {
				reference_doctype: frm.doctype,
				reference_name: frm.docname,
			},
			callback(r) {
				if (!r.message) return;
				const { status, tracking_url, driver_url } = r.message;

				// On-demand only — no frappe.msgprint() announcing this on
				// its own. A modal popping up the instant a driver gets
				// assigned caught staff off guard ("tiba-tiba ada modal,
				// link apa ini?"). Clicking this icon is how they ask to
				// see the links, instead of the links being pushed at them.
				frm.page.add_action_icon(
					"es-line-location",
					() => show_live_tracking_dialog(status, tracking_url, driver_url),
					"live-tracking-icon",
					__("Live Tracking")
				);

				frm.dashboard.add_indicator(
					__("Live Tracking: {0}", [status]),
					status === "Active" ? "green" : status === "Completed" ? "blue" : "orange"
				);
			},
		});
	},
});

function show_live_tracking_dialog(status, tracking_url, driver_url) {
	const indicator_color = status === "Active" ? "green" : status === "Completed" ? "blue" : "orange";

	const link_row = (label, url) => `
		<div class="lt-link-row" style="display:flex; align-items:center; justify-content:space-between; gap:10px; padding:10px 0; border-bottom:1px solid var(--border-color);">
			<div style="min-width:0;">
				<div style="font-weight:600;">${label}</div>
				<a href="${url}" target="_blank" style="font-size:12px; word-break:break-all;">${url}</a>
			</div>
			<button class="btn btn-xs btn-default lt-copy-btn" data-url="${frappe.utils.escape_html(url)}">${__("Salin")}</button>
		</div>
	`;

	const dialog = new frappe.ui.Dialog({
		title: __("Live Tracking"),
		fields: [
			{
				fieldtype: "HTML",
				fieldname: "links_html",
				options: `
					<div style="margin-bottom:8px;">
						<span class="indicator ${indicator_color}">${__(status)}</span>
					</div>
					${link_row(__("Link Customer"), tracking_url)}
					${link_row(__("Link Driver"), driver_url)}
				`,
			},
		],
		primary_action_label: __("Buka Dashboard Armada"),
		primary_action() {
			dialog.hide();
			frappe.set_route("live-tracking-dashboard");
		},
	});

	dialog.$wrapper.on("click", ".lt-copy-btn", function () {
		frappe.utils.copy_to_clipboard($(this).data("url"));
		frappe.show_alert({ message: __("Link disalin"), indicator: "green" });
	});

	dialog.show();
}
